i fix mine by replace 
 return Error(error);
with
 return Response.json({ error: error.message }, { status: 500 });

You can add `Promise<never>` as return type:

```ts
export async function GET(request: Request): Promise<never> {
  redirect('https://nextjs.org/')
}
```

Got this error too with my revalidate api endpoint `src/app/api/revalidate/route.ts` :

```ts
import { type NextRequest, NextResponse } from 'next/server';
import { revalidatePath, revalidateTag } from 'next/cache';

export const runtime = 'edge';

export async function GET(request: NextRequest) {

    const token: string | null =  request.headers.get('token') ? request.headers.get('token') : request.nextUrl.searchParams.get('token')
    
    if (token !== process.env.REVALIDATE_TOKEN) {
        return NextResponse.json({ error: 'Invalid token' }, { status: 401 });
    } else {

        const path: string | null =  request.headers.get('path') ? request.headers.get('path') : request.nextUrl.searchParams.get('path')
        const tag: string | null =  request.headers.get('tag') ? request.headers.get('tag') : request.nextUrl.searchParams.get('tag')

        if (!path && !tag) {
            return NextResponse.json({ error: 'Missing Params' }, { status: 400 });
        } else {
            if (path) {
                revalidatePath(path);
                return NextResponse.json({ revalidated: true, path: path, now: Date.now() }, { status: 200 });
            } else if (tag) {
                revalidateTag(tag);
                return NextResponse.json({ revalidated: true, tag: tag, now: Date.now() }, { status: 200 });
            }
        }
    }
}

export async function POST(request: NextRequest) {
    return NextResponse.json({ msg: 'not implemented yet' }, { status: 200 });
}
```

